export const LEGAL: Record<"terms"|"privacy"|"contact", LegalDocContent> = {"terms": {"titleEn": "Terms of Service", "titleAr": "شروط الخدمة", "draftEn": "DRAFT. Working draft pending review and approval by licensed legal counsel in the Kingdom of Saudi Arabia; not yet binding.", "draftAr": "مسودة. مسودة عمل بانتظار المراجعة والاعتماد من مستشار قانوني مرخص في المملكة العربية السعودية، ولا تشكل بعد شروطاً ملزمة.", "sections": [{"hEn": "Acceptance of Terms", "hAr": "قبول الشروط", "en": "These Terms of Service (the \"Terms\") govern your access to and use of the SAT Markets platform, at satmarkets.sa, including its websites, applications, tools, the Rent Index, and the SAT Advisor (the \"Platform\"). The Platform is operated by SAT Real Estate, a real estate company based in Riyadh, Kingdom of Saudi Arabia, holding FAL advertising licence 1200025510 issued under the framework of the Real Estate General Authority (REGA) [COUNSEL: confirm full legal entity name, commercial registration number, and registered address]. By creating an account, submitting a listing, making an enquiry, or otherwise using the Platform, you confirm you have read, understood, and agree to be bound by these Terms and by any policies referenced in them, including the Privacy Policy. If you do not agree, you must not use the Platform. If you use the Platform for a company or other legal entity, you represent you are duly authorised to bind that entity, and \"you\" refers to that entity.", "ar": "تحكم شروط الخدمة هذه (\"الشروط\") وصولك إلى منصة سات ماركتس واستخدامك لها عبر satmarkets.sa، بما في ذلك مواقعها وتطبيقاتها وأدواتها ومؤشر الإيجار والمستشار الذكي (\"المنصة\"). تُشغَّل المنصة من قبل شركة سات العقارية، وهي شركة عقارية مقرها الرياض، المملكة العربية السعودية، وتحمل رخصة إعلانات عقارية (فال) رقم 1200025510 الصادرة وفق إطار الهيئة العامة للعقار [COUNSEL: تأكيد الاسم القانوني الكامل ورقم السجل التجاري والعنوان المسجل]. بإنشائك حساباً أو تقديمك إعلاناً أو إرسالك استفساراً أو استخدامك المنصة، فإنك تقر بأنك قرأت هذه الشروط وفهمتها ووافقت على الالتزام بها وبأي سياسات مشار إليها فيها، بما في ذلك سياسة الخصوصية. وإذا لم توافق، فيجب عليك عدم استخدام المنصة. وإذا كنت تستخدم المنصة نيابة عن شركة أو كيان قانوني، فإنك تقر بأنك مفوض حسب الأصول بإلزام ذلك الكيان، ويُقصد بكلمة \"أنت\" ذلك الكيان."}, {"hEn": "Marketplace & SAT's Neutral Intermediary Role", "hAr": "السوق ودور سات كوسيط محايد", "en": "SAT Markets is a commercial real estate leasing and sales exchange for the Kingdom of Saudi Arabia. It enables verified owners and licensed brokers to publish verified listings, and enables prospective tenants and buyers to discover listings, make enquiries, and track transaction milestones. SAT Markets is a neutral marketplace and technology intermediary only. Without limitation: (a) SAT is not a party to, and does not sign, any lease, sale, or other contract between users; all transactions, including Ejar contracts, deposits, payments, and registration, are concluded directly between the tenant/buyer and the verified owner or their licensed broker; (b) SAT does not hold, escrow, transmit, or otherwise handle transaction funds of any kind; (c) SAT does not charge, assume, or deduct any commission by default; any representation, advisory, or brokerage engagement by SAT exists only where you explicitly opt in via a separate written agreement; (d) SAT's role is limited to verifying identity and licensing of listing parties, publishing verified listings and market data, and tracking milestones as reported by the parties. Nothing on the Platform creates an agency, partnership, joint venture, employment, fiduciary, or brokerage relationship between SAT and any user except under an explicit opt-in agreement.", "ar": "سات ماركتس منصة تبادل لتأجير وبيع العقارات التجارية في المملكة العربية السعودية. تتيح للملاك الموثقين والوسطاء المرخصين نشر إعلانات موثقة، وتتيح للمستأجرين والمشترين استكشاف الإعلانات وتقديم الاستفسارات ومتابعة مراحل الصفقة. إن سات ماركتس سوق محايدة ووسيط تقني فقط. ودون حصر: (أ) لا تكون سات طرفاً في أي عقد إيجار أو بيع بين المستخدمين ولا توقّع عليه؛ إذ تُبرم جميع الصفقات، بما في ذلك عقود منصة إيجار والعرابين والمدفوعات والتسجيل، مباشرة بين المستأجر أو المشتري وبين المالك الموثق أو وسيطه المرخص؛ (ب) لا تحتفظ سات بأموال الصفقات ولا تودعها لدى طرف ثالث ولا تحوّلها ولا تتعامل معها بأي شكل؛ (ج) لا تفرض سات ولا تفترض ولا تقتطع أي عمولة بشكل تلقائي؛ ولا ينشأ أي تمثيل أو استشارة أو وساطة من قبل سات إلا إذا اخترت ذلك صراحة بموجب اتفاقية مكتوبة مستقلة؛ (د) يقتصر دور سات على التحقق من هوية أطراف الإعلان وتراخيصهم، ونشر الإعلانات الموثقة وبيانات السوق، ومتابعة مراحل الصفقة وفق ما يبلغ عنه الأطراف. ولا ينشئ أي مما تتضمنه المنصة علاقة وكالة أو شراكة أو مشروع مشترك أو توظيف أو ائتمان أو وساطة بين سات وأي مستخدم إلا بموجب اتفاقية اشتراك صريحة."}, {"hEn": "Eligibility & Verification", "hAr": "الأهلية والتحقق", "en": "Use of the Platform is available only to persons with full legal capacity under KSA law and to duly established legal entities. Publishing a listing is restricted to (a) owners whose ownership has been verified by SAT against official records, and (b) brokers holding a valid FAL licence issued by REGA. You agree to provide accurate, current, and complete information during registration and verification, keep it updated, and promptly notify SAT of any change affecting your verification status (including suspension, expiry, or revocation of a FAL licence, or a change in ownership of a listed property). SAT may request supporting documents, verify against official sources including REGA and Ejar records [COUNSEL: confirm scope of permitted verification sources and any consents required], and may refuse, suspend, or remove any account or listing that fails verification. Verification confirms identity and licensing at the time of verification; it is not a guarantee, endorsement, or warranty of any party, property, or transaction.", "ar": "يقتصر استخدام المنصة على ذوي الأهلية القانونية الكاملة بموجب أنظمة المملكة وعلى الكيانات القانونية المؤسسة حسب الأصول. ويقتصر نشر الإعلانات على: (أ) الملاك الذين تحققت سات من ملكيتهم بالرجوع إلى السجلات الرسمية؛ (ب) الوسطاء الحاصلين على رخصة فال سارية صادرة عن الهيئة العامة للعقار. وتوافق على تقديم معلومات دقيقة وحديثة وكاملة أثناء التسجيل والتحقق، وتحديثها باستمرار، وإخطار سات فوراً بأي تغيير يؤثر في حالة التحقق (بما في ذلك تعليق رخصة فال أو انتهاؤها أو إلغاؤها أو تغير ملكية عقار معلن). ويجوز لسات طلب مستندات مؤيدة، والتحقق لدى المصادر الرسمية بما فيها سجلات الهيئة العامة للعقار ومنصة إيجار [COUNSEL: تأكيد نطاق مصادر التحقق وأي موافقات لازمة]، ورفض أو تعليق أو إزالة أي حساب أو إعلان لا يجتاز التحقق. ويقتصر التحقق على تأكيد الهوية والترخيص وقت إجرائه، ولا يشكل ضماناً أو تزكية أو كفالة لأي طرف أو عقار أو صفقة."}, {"hEn": "Acceptable Use", "hAr": "الاستخدام المقبول", "en": "You agree to use the Platform only for lawful purposes connected with commercial real estate leasing and sales in KSA. You must not: (a) publish false, misleading, duplicated, or unauthorised listings, or advertise a property without the legal right; (b) misrepresent identity, ownership, licence status, or authority; (c) circumvent, manipulate, or interfere with verification, milestone tracking, the Rent Index, or the SAT Advisor; (d) scrape or systematically extract data, or use Platform data to train models or build competing products, without SAT's prior written consent; (e) upload malicious code or attempt unauthorised access; (f) send spam/unsolicited communications or harass users; (g) violate any applicable law, including REGA regulations on real estate advertising and brokerage. SAT may suspend or terminate access, remove content, and report violations to competent authorities where required.", "ar": "توافق على استخدام المنصة للأغراض المشروعة المتصلة بتأجير وبيع العقارات التجارية في المملكة فقط. ويُحظر عليك: (أ) نشر إعلانات كاذبة أو مضللة أو مكررة أو غير مصرح بها، أو الإعلان عن عقار دون حق قانوني؛ (ب) تقديم معلومات مغلوطة عن هويتك أو ملكيتك أو ترخيصك أو صفتك؛ (ج) الالتفاف على التحقق أو متابعة المراحل أو مؤشر الإيجار أو المستشار الذكي أو التلاعب بها؛ (د) كشط البيانات أو استخراجها منهجياً، أو استخدام بيانات المنصة لتدريب نماذج أو بناء منتجات منافسة دون موافقة كتابية مسبقة؛ (هـ) رفع برمجيات خبيثة أو محاولة الوصول غير المصرح به؛ (و) إرسال رسائل مزعجة أو التحرش بالمستخدمين؛ (ز) مخالفة أي نظام معمول به، بما في ذلك لوائح الهيئة العامة للعقار بشأن الإعلانات والوساطة. ويجوز لسات تعليق الوصول أو إنهاؤه وإزالة المحتوى وإبلاغ الجهات المختصة متى لزم."}, {"hEn": "Listing Accuracy, Rent Index & SAT Advisor", "hAr": "دقة الإعلانات ومؤشر الإيجار والمستشار الذكي", "en": "Listing parties are solely responsible for the accuracy, completeness, and lawfulness of their listings (prices, areas, permitted uses, availability, imagery) and for keeping them current. SAT verifies identity and licensing and applies reasonable review procedures but does not independently inspect properties and does not warrant any listing is free of error. The Rent Index provides indicative market benchmarks derived from verified listing and transaction data; it is for general information only, is not a valuation, appraisal, or recommendation, and must not be relied upon as the sole basis for any leasing, purchase, investment, or pricing decision. The SAT Advisor is an AI tool grounded in the verified index and Platform data; its outputs are automatically generated, may contain errors or omissions, are indicative only, and do not constitute professional advice. You are responsible for independently verifying any information material to your decisions, including through your own inspections and professional advisers.", "ar": "تقع على أطراف الإعلان وحدهم مسؤولية دقة إعلاناتهم واكتمالها ومشروعيتها (الأسعار والمساحات والاستخدامات والتوفر والصور) وتحديثها باستمرار. وتتحقق سات من الهوية والترخيص وتطبق إجراءات مراجعة معقولة، غير أنها لا تعاين العقارات بشكل مستقل ولا تضمن خلو أي إعلان من الخطأ. ويقدم مؤشر الإيجار معايير سوقية استرشادية مستمدة من بيانات الإعلانات والصفقات الموثقة، وهو لأغراض المعلومات العامة فقط، ولا يشكل تقييماً أو تثميناً أو توصية، ولا يجوز الاعتماد عليه أساساً وحيداً لأي قرار استئجار أو شراء أو استثمار أو تسعير. والمستشار الذكي أداة ذكاء اصطناعي تستند إلى المؤشر الموثق وبيانات المنصة، ومخرجاته مولدة آلياً وقد تتضمن أخطاء، وهي استرشادية فقط ولا تشكل مشورة مهنية. وتتحمل أنت مسؤولية التحقق المستقل من أي معلومات جوهرية لقراراتك."}, {"hEn": "No Legal, Financial or Investment Advice", "hAr": "عدم تقديم مشورة قانونية أو مالية أو استثمارية", "en": "Nothing on the Platform, including the Rent Index, the SAT Advisor, milestone tracking, articles, or communications from SAT, constitutes legal, financial, tax, investment, valuation, or brokerage advice, and no content should be treated as a substitute for advice from appropriately licensed professionals. Obtain independent professional advice before entering into any lease, purchase, or other transaction.", "ar": "لا يشكل أي مما تتضمنه المنصة، بما في ذلك مؤشر الإيجار والمستشار الذكي ومتابعة المراحل والمقالات والمراسلات، مشورة قانونية أو مالية أو ضريبية أو استثمارية أو تقييمية أو وساطة، ولا يجوز اعتبار أي محتوى بديلاً عن مشورة المختصين المرخصين. واحصل على مشورة مهنية مستقلة قبل إبرام أي عقد إيجار أو شراء أو صفقة."}, {"hEn": "Intellectual Property", "hAr": "الملكية الفكرية", "en": "The Platform, including software, design, trademarks, trade names, the Rent Index methodology and outputs, the SAT Advisor, and all SAT-created content, is owned by SAT Real Estate or its licensors and protected under KSA intellectual property law and applicable international treaties. SAT grants you a limited, non-exclusive, non-transferable, revocable licence to use the Platform for its intended purposes. By submitting listings, images, or other content, you retain ownership and grant SAT a worldwide, royalty-free, non-exclusive licence to host, display, reproduce, and distribute it to operate, promote, and improve the Platform, including in aggregated and anonymised form within the Rent Index. You represent you hold all rights necessary to grant this licence. You may not copy, republish, or commercially exploit any Platform content, including Rent Index data, without SAT's prior written consent.", "ar": "تعود ملكية المنصة، بما في ذلك برمجياتها وتصميمها وعلاماتها وأسماؤها التجارية ومنهجية مؤشر الإيجار ومخرجاته والمستشار الذكي وكل ما تنشئه سات، إلى شركة سات العقارية أو الجهات المرخصة لها، وهي محمية بموجب أنظمة الملكية الفكرية في المملكة والاتفاقيات الدولية. وتمنحك سات ترخيصاً محدوداً غير حصري وغير قابل للتحويل وقابلاً للإلغاء لاستخدام المنصة لأغراضها. وبتقديمك إعلانات أو صوراً أو محتوى، تحتفظ بملكيته وتمنح سات ترخيصاً عالمياً غير حصري ومعفى من الرسوم لاستضافته وعرضه ونسخه وتوزيعه لتشغيل المنصة والترويج لها وتطويرها، بما في ذلك في صورة مجمعة ومجهولة الهوية ضمن مؤشر الإيجار. وتقر بأنك تملك جميع الحقوق اللازمة لمنح هذا الترخيص. ولا يجوز لك نسخ أي محتوى أو إعادة نشره أو استغلاله تجارياً، بما في ذلك بيانات مؤشر الإيجار، دون موافقة كتابية مسبقة."}, {"hEn": "Disclaimers & Limitation of Liability", "hAr": "إخلاء المسؤولية وحدودها", "en": "The Platform is provided \"as is\" and \"as available\". To the maximum extent permitted by KSA law, SAT disclaims all warranties, express or implied, including fitness for a particular purpose and non-infringement, and does not warrant the Platform will be uninterrupted, error-free, or secure. Because SAT is not a party to transactions between users, SAT is not responsible for the conduct of any user, the condition or legal status of any property, the performance or non-performance of any lease or sale contract, the handling of any deposit or payment, or any dispute between transacting parties. To the maximum extent permitted, SAT shall not be liable for any indirect, incidental, consequential, or special damages, or loss of profits, revenue, data, or business opportunity, and SAT's aggregate liability arising from or related to the Platform shall not exceed the fees actually paid by you to SAT in the twelve months preceding the event giving rise to the claim, or [COUNSEL: confirm liability cap amount and enforceability of the cap and exclusions under Saudi law] where no fees were paid. Nothing excludes liability that cannot be excluded under mandatory provisions of Saudi law.", "ar": "تُقدَّم المنصة \"كما هي\" و\"حسب توفرها\". وإلى الحد الأقصى الذي تجيزه أنظمة المملكة، تخلي سات مسؤوليتها عن جميع الضمانات الصريحة والضمنية، بما في ذلك الملاءمة لغرض معين وعدم التعدي، ولا تضمن عمل المنصة دون انقطاع أو خطأ أو أنها آمنة تماماً. ولما كانت سات ليست طرفاً في الصفقات، فهي غير مسؤولة عن سلوك أي مستخدم، أو حالة أي عقار أو وضعه القانوني، أو تنفيذ أي عقد إيجار أو بيع، أو التعامل مع أي عربون أو دفعة، أو أي نزاع بين الأطراف. وإلى الحد الأقصى المسموح، لا تتحمل سات المسؤولية عن أي أضرار غير مباشرة أو عرضية أو تبعية أو خاصة، ولا عن خسارة الأرباح أو الإيرادات أو البيانات أو الفرص، ولا يتجاوز إجمالي مسؤوليتها الرسوم التي دفعتها فعلياً خلال الاثني عشر شهراً السابقة للواقعة، أو [COUNSEL: تأكيد سقف المسؤولية ومدى نفاذه بموجب النظام السعودي] عند عدم دفع رسوم. ولا يُستبعَد ما لا يجوز استبعاده بموجب الأحكام الآمرة."}, {"hEn": "Indemnity", "hAr": "التعويض", "en": "You agree to indemnify and hold harmless SAT Real Estate, its directors, officers, employees, and agents from any claims, liabilities, damages, losses, and expenses (including reasonable legal fees) arising out of or connected with (a) your breach of these Terms, (b) your listings, content, or communications, (c) your transactions with other users, or (d) your violation of any applicable law or the rights of any third party.", "ar": "توافق على تعويض شركة سات العقارية وأعضاء مجلس إدارتها ومسؤوليها وموظفيها ووكلائها وإبراء ذمتهم من أي مطالبات أو التزامات أو أضرار أو خسائر أو مصاريف (بما فيها الأتعاب القانونية المعقولة) تنشأ عن أو تتصل بـ: (أ) إخلالك بهذه الشروط؛ (ب) إعلاناتك أو محتواك أو مراسلاتك؛ (ج) صفقاتك مع المستخدمين الآخرين؛ (د) مخالفتك لأي نظام أو لحقوق أي طرف ثالث."}, {"hEn": "Governing Law & Dispute Resolution", "hAr": "النظام الواجب التطبيق وتسوية المنازعات", "en": "These Terms are governed by and construed in accordance with the laws and regulations of the Kingdom of Saudi Arabia. Any dispute between you and SAT shall first be addressed through good-faith negotiation with SAT's support team. If not resolved within thirty (30) days, it shall be referred to the competent courts or judicial committees of KSA in Riyadh [COUNSEL: confirm forum, e.g. competent commercial court vs. arbitration under the Saudi Center for Commercial Arbitration, and any REGA-mandated dispute channels]. For clarity, disputes between transacting parties (e.g., a tenant and an owner over an Ejar contract) are matters between those parties under the mechanisms applicable to their direct contract; SAT is not a party to such disputes.", "ar": "تخضع هذه الشروط لأنظمة ولوائح المملكة العربية السعودية وتُفسَّر وفقاً لها. وتُعالَج أي منازعة بينك وبين سات أولاً عبر التفاوض بحسن نية مع فريق الدعم. فإذا لم تُسوَّ خلال ثلاثين (30) يوماً، تُحال إلى المحاكم أو اللجان القضائية المختصة في المملكة بمدينة الرياض [COUNSEL: تأكيد جهة الاختصاص، مثل المحكمة التجارية المختصة أو التحكيم لدى المركز السعودي للتحكيم التجاري، وأي قنوات إلزامية لدى الهيئة العامة للعقار]. وللإيضاح، فإن المنازعات بين أطراف الصفقة (كالمنازعة بين مستأجر ومالك بشأن عقد إيجار) شأن خاص بأولئك الأطراف وتخضع للآليات المطبقة على عقدهم المباشر، ولا تكون سات طرفاً فيها."}, {"hEn": "Changes to These Terms", "hAr": "التعديلات على هذه الشروط", "en": "SAT may amend these Terms to reflect changes in the Platform, applicable law, or regulatory requirements. Material changes will be notified through the Platform or by email at least [COUNSEL: confirm notice period, e.g. 14 or 30 days] before taking effect. Continued use after the effective date constitutes acceptance. If you do not accept a change, stop using the Platform and you may close your account.", "ar": "يجوز لسات تعديل هذه الشروط بما يعكس التغييرات في المنصة أو الأنظمة أو المتطلبات التنظيمية. ويُخطَر المستخدمون بالتعديلات الجوهرية عبر المنصة أو البريد الإلكتروني قبل نفاذها بمدة لا تقل عن [COUNSEL: تأكيد مدة الإشعار، مثلاً 14 أو 30 يوماً]. ويُعد استمرارك بعد النفاذ قبولاً. وإذا لم تقبل التعديل، فتوقف عن الاستخدام ويجوز لك إغلاق حسابك."}, {"hEn": "Contact", "hAr": "التواصل", "en": "Questions about these Terms: SAT Real Estate, Riyadh, KSA, FAL licence 1200025510, at [COUNSEL: confirm legal notices email] or via the Contact page.", "ar": "أسئلة الشروط: شركة سات العقارية، الرياض، المملكة، رخصة فال 1200025510، عبر [COUNSEL: تأكيد البريد الإلكتروني للإشعارات القانونية] أو من خلال صفحة \"اتصل بنا\"."}]}, "privacy": {"titleEn": "Privacy Policy (PDPL)", "titleAr": "سياسة الخصوصية (نظام حماية البيانات الشخصية)", "draftEn": "DRAFT. Pending review and approval by licensed KSA legal counsel; not yet a binding privacy notice.", "draftAr": "مسودة. بانتظار المراجعة والاعتماد من مستشار قانوني مرخص في المملكة؛ ولا تشكل بعد إشعار خصوصية ملزماً.", "sections": [{"hEn": "Data Controller", "hAr": "جهة التحكم بالبيانات", "en": "This Privacy Policy explains how SAT Real Estate (\"SAT\", \"we\"), operator of SAT Markets (satmarkets.sa) and holder of FAL licence 1200025510, based in Riyadh, KSA, collects and processes personal data. SAT Real Estate is the data controller within the meaning of the Saudi Personal Data Protection Law (PDPL) and its Implementing Regulations [COUNSEL: confirm full legal entity name, CR number, and registered address]. This Policy applies to the Platform, our applications, and related communications.", "ar": "توضح هذه السياسة كيف تجمع شركة سات العقارية (\"سات\"، \"نحن\")، مشغلة سات ماركتس (satmarkets.sa) والحاصلة على رخصة فال 1200025510 ومقرها الرياض، البيانات الشخصية وتعالجها. وتُعد شركة سات العقارية جهة التحكم بالمعنى الوارد في نظام حماية البيانات الشخصية ولوائحه التنفيذية [COUNSEL: تأكيد الاسم القانوني الكامل ورقم السجل التجاري والعنوان المسجل]. وتسري على المنصة وتطبيقاتنا والمراسلات ذات الصلة."}, {"hEn": "Personal Data We Collect", "hAr": "البيانات التي نجمعها", "en": "(a) Account and verification data: name, national ID/Iqama or commercial registration details as required, FAL licence number for brokers, ownership documentation references, and account credentials [COUNSEL: confirm exact identity documents collected and whether copies are retained]; (b) Contact data: email, phone, business address; (c) Listing and enquiry data: property details, enquiries sent/received, on-platform messages, milestone records; (d) Usage and technical data: device info, IP address, logs, and interactions including SAT Advisor queries; (e) Cookie data (Section 9). We collect from you, from your Platform interactions, and for verification from official sources including REGA and Ejar where permitted.", "ar": "(أ) بيانات الحساب والتحقق: الاسم، ورقم الهوية/الإقامة أو بيانات السجل التجاري، ورقم رخصة فال للوسطاء، ومراجع مستندات الملكية، وبيانات اعتماد الحساب [COUNSEL: تأكيد مستندات الهوية المجمعة وما إذا كان يُحتفظ بنسخ]؛ (ب) بيانات التواصل: البريد والهاتف وعنوان العمل؛ (ج) بيانات الإعلانات والاستفسارات: تفاصيل العقارات، والاستفسارات المرسلة/المتلقاة، والرسائل داخل المنصة، وسجلات المراحل؛ (د) بيانات الاستخدام والتقنية: معلومات الجهاز وعنوان IP والسجلات والتفاعلات بما فيها استعلامات المستشار الذكي؛ (هـ) بيانات ملفات تعريف الارتباط (البند 9). ونجمعها منك ومن تفاعلاتك ومن المصادر الرسمية للتحقق بما فيها الهيئة العامة للعقار ومنصة إيجار حيثما سُمح."}, {"hEn": "Lawful Basis & Purposes", "hAr": "الأساس النظامي والأغراض", "en": "Under the PDPL: (a) performance of our agreement: accounts, listings, facilitating enquiries between verified parties, milestone tracking; (b) legal obligations: identity/licence verification under REGA, record-keeping, ZATCA-compliant e-invoicing for any SAT fees, lawful requests by authorities; (c) legitimate interests consistent with the PDPL: securing the Platform, preventing fraud/misuse, improving services including the Rent Index and SAT Advisor using aggregated and, where feasible, anonymised data [COUNSEL: confirm reliance on legitimate interest under the PDPL and Implementing Regulations for each purpose]; (d) your consent: marketing and non-essential cookies, withdrawable anytime without affecting core use.", "ar": "بموجب النظام: (أ) تنفيذ اتفاقيتنا: الحسابات والإعلانات وتيسير الاستفسارات بين الأطراف الموثقة ومتابعة المراحل؛ (ب) الالتزامات النظامية: التحقق من الهوية/الترخيص وفق الهيئة العامة للعقار، وحفظ السجلات، والفوترة الإلكترونية المتوافقة مع هيئة الزكاة والضريبة والجمارك، والاستجابة للطلبات النظامية؛ (ج) المصالح المشروعة: تأمين المنصة ومنع الاحتيال وتحسين الخدمات بما فيها مؤشر الإيجار والمستشار الذكي ببيانات مجمعة ومجهولة الهوية حيثما أمكن [COUNSEL: تأكيد الاستناد إلى المصلحة المشروعة بموجب النظام ولوائحه لكل غرض]؛ (د) موافقتك: التسويق وملفات تعريف الارتباط غير الضرورية، ويجوز سحبها في أي وقت دون التأثير في الاستخدام الأساسي."}, {"hEn": "Your Rights Under the PDPL", "hAr": "حقوقك بموجب النظام", "en": "Subject to PDPL conditions and exceptions, you may: (a) be informed; (b) access and obtain a copy; (c) request correction, completion, or updating; (d) request destruction when data is no longer needed; (e) withdraw consent at any time; (f) object to certain processing as provided [COUNSEL: confirm current scope of the objection right under the Implementing Regulations]. We respond within the PDPL timeframes. Free of charge except where regulations permit a fee for repetitive or manifestly excessive requests.", "ar": "مع مراعاة شروط النظام واستثناءاته، لك: (أ) العلم؛ (ب) الوصول والحصول على نسخة؛ (ج) طلب التصحيح أو الإكمال أو التحديث؛ (د) طلب الإتلاف متى انتفت الحاجة؛ (هـ) سحب الموافقة في أي وقت؛ (و) الاعتراض على بعض المعالجة وفق ما يقرره النظام [COUNSEL: تأكيد نطاق حق الاعتراض بموجب اللوائح]. ونستجيب خلال المدد المقررة. ودون مقابل، إلا حيثما تجيز اللوائح مقابلاً عن الطلبات المتكررة أو المفرطة."}, {"hEn": "Data Sharing", "hAr": "مشاركة البيانات", "en": "Only as necessary: (a) verified counterparties: when you make/receive an enquiry, relevant contact and enquiry details are shared with the verified owner or licensed broker so parties transact directly; (b) licensed brokers acting for a listing party, as needed; (c) service providers (hosting, identity verification, analytics, communications) under PDPL-consistent contracts [COUNSEL: confirm processor list and DPA terms]; (d) REGA, Ejar, ZATCA, and competent authorities where required; (e) corporate restructuring/merger/acquisition with safeguards. We do not sell personal data and do not share it with advertisers for their own purposes.", "ar": "بالقدر اللازم فقط: (أ) الأطراف الموثقة: عند تقديم/تلقي استفسار تُتبادل بيانات التواصل والاستفسار مع المالك الموثق أو الوسيط المرخص ليتعامل الأطراف مباشرة؛ (ب) الوسطاء المرخصون لطرف الإعلان بالقدر اللازم؛ (ج) مقدمو الخدمات (الاستضافة والتحقق والتحليلات والاتصالات) بعقود متوافقة مع النظام [COUNSEL: تأكيد قائمة المعالجين وبنود الاتفاقيات]؛ (د) الهيئة العامة للعقار ومنصة إيجار وهيئة الزكاة والضريبة والجمارك والجهات المختصة عند اللزوم؛ (هـ) إعادة الهيكلة أو الاندماج أو الاستحواذ مع الضمانات. ولا نبيع البيانات ولا نشاركها مع المعلنين لأغراضهم."}, {"hEn": "Cross-Border Transfers", "hAr": "نقل البيانات خارج المملكة", "en": "Default posture: store and process personal data within KSA. Where transfer outside the Kingdom is necessary (e.g., a cloud or support provider), only in accordance with the PDPL and the Regulation on Personal Data Transfer Outside the Kingdom (adequacy, appropriate safeguards such as standard contractual clauses, or another lawful mechanism), limited to the minimum data necessary [COUNSEL: confirm actual hosting locations, transfer mechanisms, and any required risk assessments or SDAIA notifications].", "ar": "الأساس: التخزين والمعالجة داخل المملكة. وحيثما لزم النقل خارجها (كمزود سحابي أو دعم)، يكون وفق النظام ولائحة نقل البيانات خارج المملكة (الملاءمة أو الضمانات المناسبة كالبنود التعاقدية القياسية أو آلية نظامية أخرى)، وبالحد الأدنى اللازم [COUNSEL: تأكيد مواقع الاستضافة وآليات النقل وأي تقييمات مخاطر أو إخطارات لسدايا]."}, {"hEn": "Retention", "hAr": "الاحتفاظ", "en": "We retain personal data only as long as necessary for the purposes described, to comply with legal/regulatory obligations (including REGA record-keeping and ZATCA invoicing), and to establish or defend legal claims; then we destroy or irreversibly anonymise it per the PDPL. Indicative: account data for the life of the account plus [COUNSEL: confirm]; verification records for [COUNSEL: confirm REGA period]; invoicing for the ZATCA-required period [COUNSEL: confirm]; usage logs for [COUNSEL: confirm].", "ar": "نحتفظ بالبيانات للمدة اللازمة للأغراض الموضحة وللامتثال للالتزامات (بما فيها حفظ سجلات الهيئة العامة للعقار وفوترة هيئة الزكاة والضريبة والجمارك) ولإثبات المطالبات أو الدفاع عنها؛ ثم نتلفها أو نخفي هويتها نهائياً وفق النظام. استرشادياً: بيانات الحساب طوال مدته مضافاً [COUNSEL: تأكيد المدة]؛ سجلات التحقق [COUNSEL: تأكيد مدة الهيئة]؛ الفوترة للمدة المقررة من هيئة الزكاة والضريبة [COUNSEL: تأكيد]؛ سجلات الاستخدام [COUNSEL: تأكيد]."}, {"hEn": "Security", "hAr": "الأمن", "en": "We apply technical and organisational measures appropriate to the data (encryption in transit, access controls, logging, staff confidentiality) consistent with the PDPL and applicable national cybersecurity requirements [COUNSEL: confirm applicability of NCA Essential Cybersecurity Controls]. No system is completely secure; if a breach harms or is likely to harm your data or interests, we will notify SDAIA and affected data subjects per the PDPL and Implementing Regulations.", "ar": "نطبق تدابير تقنية وتنظيمية مناسبة (التشفير أثناء النقل وضوابط الوصول والتسجيل والتزامات السرية) بما يتفق مع النظام ومتطلبات الأمن السيبراني الوطنية [COUNSEL: تأكيد انطباق الضوابط الأساسية للهيئة الوطنية للأمن السيبراني]. ولا يوجد نظام آمن تماماً؛ وعند وقوع اختراق يضر أو يُحتمل أن يضر ببياناتك أو مصالحك، نُخطر سدايا وأصحاب البيانات المتأثرين وفق النظام ولوائحه."}, {"hEn": "Cookies", "hAr": "ملفات تعريف الارتباط", "en": "Essential cookies are always active (authentication, security). Non-essential cookies (analytics, preferences) are used only with your consent and declined by default; accept or manage them via the cookie banner and settings anytime. We do not use non-essential cookies for third-party behavioural advertising [COUNSEL: confirm final cookie inventory and third-party tools].", "ar": "ملفات تعريف الارتباط الضرورية مفعلة دائماً (المصادقة والأمان). وغير الضرورية (التحليلات والتفضيلات) لا تُستخدم إلا بموافقتك وتكون مرفوضة افتراضياً؛ اقبلها أو أدرها عبر الشريط والإعدادات في أي وقت. ولا نستخدمها للإعلانات السلوكية لدى أطراف ثالثة [COUNSEL: تأكيد القائمة النهائية والأدوات]."}, {"hEn": "Children's Data", "hAr": "بيانات القاصرين", "en": "The Platform is a commercial real estate service for businesses and adults with legal capacity. It is not directed at minors, and we do not knowingly collect data from anyone under 18. If we learn a minor's data was collected, we delete it promptly.", "ar": "المنصة خدمة عقارية تجارية للمنشآت والراشدين ذوي الأهلية، وهي غير موجهة للقاصرين، ولا نجمع عن علم بيانات من تقل أعمارهم عن 18 عاماً. وإذا علمنا بذلك، نحذفها فوراً."}, {"hEn": "Exercising Rights & Contact", "hAr": "ممارسة الحقوق والتواصل", "en": "To exercise any PDPL right or raise a privacy concern, contact the controller, SAT Real Estate, at [COUNSEL: confirm dedicated privacy email, e.g. privacy@satmarkets.sa] or by mail to [COUNSEL: confirm registered address], attn. Data Protection Officer [COUNSEL: confirm whether a DPO is appointed and required]. We may verify your identity first. If unsatisfied, you may complain to the Saudi Data and Artificial Intelligence Authority (SDAIA), the PDPL supervisory authority.", "ar": "لممارسة أي حق أو استفسار خصوصية، تواصل مع جهة التحكم شركة سات العقارية عبر [COUNSEL: تأكيد بريد الخصوصية، مثل privacy@satmarkets.sa] أو بالبريد على [COUNSEL: تأكيد العنوان المسجل]، عناية مسؤول حماية البيانات [COUNSEL: تأكيد تعيينه]. وقد نتحقق من هويتك أولاً. وإذا لم تكن راضياً، فلك تقديم شكوى إلى الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)."}, {"hEn": "Changes", "hAr": "التعديلات", "en": "We may update this Policy; material changes notified via the Platform or email before they take effect, with a revised \"last updated\" date. Continued use constitutes acknowledgement. Last updated: [COUNSEL: insert date upon approval].", "ar": "قد نحدّث هذه السياسة؛ ويُخطَر بالتعديلات الجوهرية عبر المنصة أو البريد قبل نفاذها مع تحديث تاريخ \"آخر تحديث\". ويُعد الاستمرار إقراراً. آخر تحديث: [COUNSEL: إدراج التاريخ عند الاعتماد]."}]}, "contact": {"titleEn": "Contact", "titleAr": "اتصل بنا", "draftEn": "DRAFT. Contact details are placeholders pending confirmation by SAT Real Estate and review by licensed counsel.", "draftAr": "مسودة. بيانات التواصل مواضع مؤقتة بانتظار تأكيدها من شركة سات العقارية ومراجعتها من مستشار قانوني.", "sections": [{"hEn": "Company Identity", "hAr": "هوية الشركة", "en": "SAT Markets is operated by SAT Real Estate, Riyadh, KSA. FAL advertising licence: 1200025510 (REGA). Commercial registration: [COUNSEL: confirm CR number]. Registered address: [COUNSEL: confirm full address, Riyadh, Saudi Arabia].", "ar": "تُشغَّل سات ماركتس من قبل شركة سات العقارية، الرياض، المملكة. رخصة فال: 1200025510 (الهيئة العامة للعقار). السجل التجاري: [COUNSEL: تأكيد الرقم]. العنوان المسجل: [COUNSEL: تأكيد العنوان الكامل، الرياض]."}, {"hEn": "General Enquiries", "hAr": "الاستفسارات العامة", "en": "General questions, partnerships, or media: Email [COUNSEL: confirm, e.g. hello@satmarkets.sa]. Phone [COUNSEL: confirm number and hours, e.g. Sun to Thu, 9:00 to 17:00 AST].", "ar": "الأسئلة العامة أو الشراكات أو الإعلام: البريد [COUNSEL: تأكيد، مثل hello@satmarkets.sa]. الهاتف [COUNSEL: تأكيد الرقم وأوقات العمل، مثل الأحد إلى الخميس، 9:00 إلى 17:00 بتوقيت المملكة]."}, {"hEn": "Listing & Verification Support", "hAr": "دعم الإعلانات والتحقق", "en": "Owner verification, FAL checks, publishing/updating a listing, or milestone tracking: Email [COUNSEL: confirm, e.g. support@satmarkets.sa]. Verified owners and licensed brokers can also reach support from their account dashboard.", "ar": "توثيق الملاك أو التحقق من رخص فال أو نشر/تحديث إعلان أو متابعة المراحل: البريد [COUNSEL: تأكيد، مثل support@satmarkets.sa]. ويمكن للملاك الموثقين والوسطاء المرخصين التواصل من لوحة التحكم."}, {"hEn": "Privacy & Data Requests", "hAr": "طلبات الخصوصية والبيانات", "en": "To exercise PDPL rights (access, correction, deletion, objection, withdrawal of consent), contact the controller, SAT Real Estate: Email [COUNSEL: confirm, e.g. privacy@satmarkets.sa]. Postal [COUNSEL: confirm registered address], attn. Data Protection Officer [COUNSEL: confirm DPO]. If unresolved, you may complain to SDAIA.", "ar": "لممارسة حقوق النظام (الوصول والتصحيح والحذف والاعتراض وسحب الموافقة)، تواصل مع جهة التحكم شركة سات العقارية: البريد [COUNSEL: تأكيد، مثل privacy@satmarkets.sa]. البريد العادي [COUNSEL: تأكيد العنوان المسجل]، عناية مسؤول حماية البيانات [COUNSEL: تأكيد]. وإذا لم يُحل، فيمكن تقديم شكوى إلى سدايا."}, {"hEn": "Deal-Specific Matters Stay On-Platform", "hAr": "شؤون الصفقات تبقى داخل المنصة", "en": "For your protection, all matters relating to a specific listing or transaction (enquiries, negotiations, document exchange, milestone updates) should be handled through your SAT Markets account, where both parties are verified and activity is recorded. SAT is a neutral intermediary: it does not sign contracts, hold funds, or take commissions by default, and cannot intervene in the terms of a deal. Be cautious of anyone requesting payments or contract signatures off-platform in SAT's name.", "ar": "حرصاً على حمايتك، ينبغي التعامل مع كل ما يخص إعلاناً أو صفقة بعينها (الاستفسارات والمفاوضات وتبادل المستندات وتحديثات المراحل) من خلال حسابك على سات ماركتس حيث يكون الطرفان موثقَين ويُسجَّل النشاط. إن سات وسيط محايد: لا توقّع العقود ولا تحتفظ بالأموال ولا تتقاضى عمولات بشكل تلقائي، ولا تتدخل في شروط أي صفقة. واحذر من أي جهة تطلب مدفوعات أو توقيع عقود خارج المنصة باسم سات."}]}};
